def perimeter_L(obj,h,w):
 cells=set(obj['cells']); r0,r1,c0,c1=obj['box']; corners=[]
 for rr in (r0,r1):
  for cc in (c0,c1):
   edge=({(rr,c) for c in range(c0,c1+1)}|{(r,cc) for r in range(r0,r1+1)})
   if cells==edge: corners.append((rr,cc))
 return corners

