 refs=[o for o in cs if perimeter_L(o,h,w) and any(r==0 or r==h-1 or c==0 or c==w-1 for r,c in o['cells'])]
 ref=max(refs,key=lambda o:len(o['cells'])) if refs else None
 groups={}
 for o in cs:
  if o is ref: continue
  groups.setdefault(canonical(o['shape']),[]).append(o)
 cand=[o for group in groups.values() if len(group)>1 for o in group]
