def components8(g):
 h,w=len(g),len(g[0]); bg=Counter(v for row in g for v in row).most_common(1)[0][0]; seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if g[r][c]==bg or (r,c) in seen:continue
   col=g[r][c]; stack=[(r,c)]; seen.add((r,c)); cells=[]
   while stack:
    x,y=stack.pop();cells.append((x,y))
    for dx in (-1,0,1):
     for dy in (-1,0,1):
      nx,ny=x+dx,y+dy
      if (dx or dy) and 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==col:seen.add((nx,ny));stack.append((nx,ny))
   r0=min(x for x,y in cells);r1=max(x for x,y in cells);c0=min(y for x,y in cells);c1=max(y for x,y in cells)
   out.append(dict(color=col,cells=cells,box=(r0,r1,c0,c1),shape=frozenset((x-r0,y-c0) for x,y in cells)))
 return out
